(() => {
'use strict';
const DATA = window.__DASHBOARD_DATA || JSON.parse(document.getElementById('study-data').textContent);
const MODEL_IDS = ['logistic_regression','knn','svm','random_forest'];
const NAMES = {logistic_regression:'Logistic Regression',knn:'KNN',svm:'RBF SVM',random_forest:'Random Forest',always_on_time:'Always on time',always_delayed:'Always delayed',fair_coin_seed42:'Fair coin · seed 42',historical_risk_ranking:'Historical risk'};
const SHORT = {logistic_regression:'Logistic Reg.',knn:'KNN',svm:'RBF SVM',random_forest:'Random Forest',always_on_time:'Always on time',always_delayed:'Always delayed',fair_coin_seed42:'Fair coin',historical_risk_ranking:'Historical risk'};
const COLORS = {logistic_regression:'#236b9f',knn:'#7962a5',svm:'#398275',random_forest:'#bf8436',historical_risk_ranking:'#8592a2',random:'#c28842'};
const PACKAGES = {combined:'Weather, pressure & traffic interactions',current_66:'Retained existing 66 features',pressure_wind:'Pressure & wind interactions'};
const PAGES = {
 performance:{id:'O1',title:'Model performance',description:'Compare four classifiers with simple baselines. The model was selected on 2025 validation; these are its later July confirmation results.'},
 features:{id:'O2',title:'What did the features add?',description:'Measure predictive gain on identical flights, using matched classifier settings. The combined package adds origin weather, history and scheduled traffic.'},
 reliability:{id:'O3',title:'Where do predictions fail?',description:'Inspect false warnings and missed delays across airports, airlines and departure time bands. Rates retain their own denominators and support rules.'},
 prioritization:{id:'O4',title:'A smaller list. Higher concentration.',description:'Explore fixed review budgets of 5%, 10% and 20%. This ranks a completed July cohort retrospectively; it is not a live alert policy.'}
};
const DEFAULTS = {page:'performance',model:'logistic_regression',feature:'B',comparisonMetric:'f1',benchmarks:true,contrast:'A',grouping:'origin',errorMetric:'false_positive_rate',group:null,quota:.1,airport:'All',outcome:'errors',search:'',listPage:1,sort:'rank',sortDirection:1,hiddenCurves:[]};
const state = {...DEFAULTS,hiddenCurves:[]};
const metricsIndex = new Map(DATA.metrics.map(r=>[r.model_id+'|'+r.feature_set,r]));
const nf = new Intl.NumberFormat('en-US');
const num = x => x == null ? '—' : nf.format(x);
const percentFormats = new Map();
const pct = (x,d=1) => {if(x==null)return '—';if(!percentFormats.has(d))percentFormats.set(d,new Intl.NumberFormat('en-US',{style:'percent',minimumFractionDigits:d,maximumFractionDigits:d}));return percentFormats.get(d).format(x);};
const dec = (x,d=3) => x == null ? '—' : Number(x).toFixed(d);
const pp = (x,d=2) => x == null ? '—' : (x>0?'+':'')+(x*100).toFixed(d)+' pp';
const esc = x => String(x ?? '').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const tip = s => `data-tip="${esc(s)}"`;
const options = (choices,current) => choices.map(([v,t])=>`<option value="${esc(v)}"${String(v)===String(current)?' selected':''}>${esc(t)}</option>`).join('');
const modelOptions = () => options(MODEL_IDS.map(id=>[id,NAMES[id]+(id==='logistic_regression'?' · validation choice':'')]),state.model);
const metric = (model=state.model,feature=state.feature) => metricsIndex.get(model+'|'+feature);
const bMetric = () => metric(state.model,'B');
const isChosen = r => r.model_id==='logistic_regression' && r.feature_set==='B';
const selectedBadge = r => isChosen(r) ? '<span class="selected-badge">★ CHOSEN</span>' : '';
const getQuota = (model=state.model,quota=state.quota) => DATA.priority.find(r=>r.model_id===model && r.feature_set===(MODEL_IDS.includes(model)?'B':'baseline') && Math.abs(r.capacity_fraction-quota)<1e-9);
const groupData = () => DATA.groups.filter(r=>r.feature_set==='B' && r.model_id===state.model && r.group_dimension===state.grouping);
const featureData = () => MODEL_IDS.map(id=>metric(id,'B'));
const baselines = () => DATA.metrics.filter(r=>r.feature_set==='baseline');
const groupingNames = {origin:'Airport',reporting_airline:'Airline',departure_time_band:'Departure time'};
const errorNames = {precision:'Precision',recall:'Recall',false_positive_rate:'False-positive rate',false_negative_rate:'Miss rate'};
const errorKeys = ['precision','recall','false_positive_rate','false_negative_rate'];
const featureName = f => ({A:'A · schedule only',reference66:'Retuned 66 · reference',B:'B · richer package'}[f]);
const actualDelays = DATA.manifest.test_rows * metric('logistic_regression','B').prevalence;

function kpi(label,value,sub,definition='',accent=false){return `<div class="kpi${accent?' accent':''}"><div class="kpi-label">${label}${definition?`<span class="help" ${tip(definition)} aria-label="${esc(definition)}">?</span>`:''}</div><div class="kpi-value">${value}</div><div class="kpi-sub">${sub}</div></div>`;}
function panel(title,subtitle,content,extra='',cls=''){return `<section class="panel ${cls}"><div class="panel-head"><div><h2>${title}</h2>${subtitle?`<p class="panel-sub">${subtitle}</p>`:''}</div>${extra}</div>${content}</section>`;}
function chart(name){return `<div class="chart" data-chart="${name}"></div>`;}
function heading(){const p=PAGES[state.page];return `<div class="heading"><div><div class="eyebrow">${p.id} / RESEARCH OBJECTIVE</div><h1>${p.title}</h1><p class="page-description">${p.description}</p></div>${state.page!=='features'?`<div class="model-control"><label class="control-label" for="model-select">Viewing model</label><select id="model-select" data-control="model">${modelOptions()}</select></div>`:''}</div><div class="registered"><span class="star" aria-hidden="true">★</span><span><strong>Validation choice: Logistic Regression · B.</strong> Exploring another model does not change the frozen selection.</span><small>2025 development → July 2026 confirmation</small></div><div class="print-heading">${NAMES[state.model]} · ${state.page==='performance'?featureName(state.feature):'Feature package B'} · July 2026 · 10,000 flights · ATL / DFW / ORD</div>`;}

function performance(){
 const r=metric(), falseShare=r.fp/r.predicted_positive;
 const rows=MODEL_IDS.map(id=>metric(id));if(state.benchmarks)rows.push(...baselines());
 const comparison=rows.map(x=>`<tr class="${x.model_id===state.model?'selected-row':''} ${x.feature_set==='baseline'?'baseline':''}"><td class="model-name">${MODEL_IDS.includes(x.model_id)?`<button data-model="${x.model_id}">${NAMES[x.model_id]}</button>`:NAMES[x.model_id]}${selectedBadge(x)}</td><td class="num">${dec(x.f1)}</td><td class="num">${dec(x.average_precision)}</td><td class="num">${pct(x.precision)}</td><td class="num">${pct(x.recall)}</td><td class="num">${pct(x.accuracy)}</td><td class="num">${num(x.fp)}</td><td class="num">${num(x.fn)}</td></tr>`).join('');
 const maxFit=Math.max(...MODEL_IDS.map(id=>metric(id).fit_seconds));
 const runtime=MODEL_IDS.map(id=>{const x=metric(id);return `<tr${id===state.model?' class="selected-row"':''}><td>${NAMES[id]}</td><td class="num"><span class="runtime-track" aria-hidden="true"><i style="width:${x.fit_seconds/maxFit*100}%"></i></span>${dec(x.fit_seconds,2)}s</td><td class="num">${dec(x.prediction_seconds,3)}s</td></tr>`;}).join('');
 return `${heading()}<div class="section-controls"><div class="control-row"><div class="control"><label class="control-label" for="feature-select">Feature set · this page</label><select id="feature-select" data-control="feature">${options([['B','B · richer package'],['A','A · schedule only'],['reference66','Retuned 66 · reference']],state.feature)}</select></div><div class="budget-meta">Same 10,000 July flights<br>${num(r.n_predictors)} predictors · frozen F1 threshold ${dec(r.decision_threshold,4)}</div></div><label class="check"><input type="checkbox" data-control="benchmarks"${state.benchmarks?' checked':''}>Include simple baselines</label></div>
 <div class="kpi-grid">${kpi('Delayed-class F1',dec(r.f1),'Balance of precision and recall','F1 = 2 × precision × recall / (precision + recall). 0.50 is not a universal coin-flip F1.',true)}${kpi('Average precision',dec(r.average_precision),'Ranking reference: prevalence 0.3215','Average precision summarizes ranking across score thresholds; it is not accuracy.')}${kpi('Actual delays found',pct(r.recall),`${num(r.tp)} of ${num(r.actual_positive)} actual delays`,'Recall = TP / (TP + FN).')}${kpi('Warning precision',pct(r.precision),`${num(r.tp)} correct / ${num(r.predicted_positive)} warnings`,'Precision = TP / (TP + FP).')}</div>
 <div class="grid two">${panel('Models & baselines',`All classifiers use ${esc(featureName(state.feature))}. Click a model bar to inspect it.`,chart('model-comparison')+'<div class="panel-foot">Higher is better for the displayed metric. Baselines are fixed references, not model candidates.</div>',`<select aria-label="Comparison metric" data-control="comparisonMetric">${options([['f1','F1'],['average_precision','Average precision'],['precision','Precision'],['recall','Recall'],['accuracy','Accuracy'],['roc_auc','ROC-AUC']],state.comparisonMetric)}</select>`)}
 ${panel('What the warning rule gets right & wrong',`${NAMES[state.model]} · ${esc(featureName(state.feature))}`,`<div class="matrix-axes"><span></span><span class="matrix-axis">Predicted delay</span><span class="matrix-axis">Predicted on time</span><span class="matrix-axis">Actually<br>delayed</span><div class="matrix tp" ${tip('True positive: an actual delay correctly warned about.')}><span class="code">TP</span><span class="count">${num(r.tp)}</span><span class="description">Delay correctly found</span></div><div class="matrix fn" ${tip('False negative / Type II error: the model misses an actual delayed departure.')}><span class="code">FN</span><span class="count">${num(r.fn)}</span><span class="description">Delay missed</span></div><span class="matrix-axis">Actually<br>on time</span><div class="matrix fp" ${tip('False positive / Type I error: warning issued for a flight that departs on time.')}><span class="code">FP</span><span class="count">${num(r.fp)}</span><span class="description">False warning</span></div><div class="matrix tn" ${tip('True negative: an on-time departure correctly given no delay warning.')}><span class="code">TN</span><span class="count">${num(r.tn)}</span><span class="description">Correctly on time</span></div></div><div class="two-metrics"><div class="small-stat"><b>${pct(falseShare)}</b><p>of warnings were false<br>FP / all warnings</p></div><div class="small-stat"><b>${pct(r.predicted_positive/r.n_flights)}</b><p>of all flights were warned<br>Warnings / 10,000</p></div></div><div class="insight warm"><strong>${pct(r.recall)} recall needs context.</strong> This threshold also creates ${num(r.fp)} false warnings. Inspect a smaller review list in O4.</div>`)}</div>
 <div class="grid two">${panel('Precision–recall trade-off',`Four classifiers · ${esc(featureName(state.feature))} · all original curve points retained.`,curveLegend()+chart('pr-curves')+'<div class="panel-foot">Dashed reference = 32.15% prevalence. Dots mark frozen classification thresholds. Toggle a legend label to compare fewer curves.</div>')}${panel('Computation & interpretation','Recorded timings from the same experimental run.',`<div class="table-wrap"><table><thead><tr><th>Classifier</th><th class="num">Final fit · 40k</th><th class="num">Predict · 10k</th></tr></thead><tbody>${runtime}</tbody></table></div><div class="insight"><strong>Selection stays separate from test ranking.</strong> KNN has July’s highest B F1 (${dec(metric('knn','B').f1)}), while Logistic Regression was chosen using earlier validation.</div><p class="objective-note">Always-on-time accuracy is ${pct(metric('always_on_time','baseline').accuracy)}, but its delayed-class F1 is zero. F1, precision and recall answer different questions from accuracy.</p><p class="hint">Timings depend on this machine and implementation; they are not a hardware-independent benchmark.</p>`)}</div>
 ${panel('Exact performance comparison',`${esc(featureName(state.feature))} classifiers${state.benchmarks?' plus fixed baselines':''}; metrics are calculated on the full July sample.`,`<div class="table-wrap"><table><thead><tr><th>Model</th><th class="num">F1</th><th class="num">AP</th><th class="num">Precision</th><th class="num">Recall</th><th class="num">Accuracy</th><th class="num">FP</th><th class="num">FN</th></tr></thead><tbody>${comparison}</tbody></table></div>`)}`;
}
function curveLegend(){return `<div class="legend">${MODEL_IDS.map(id=>`<button data-curve="${id}" aria-pressed="${!state.hiddenCurves.includes(id)}"><i class="swatch" style="background:${COLORS[id]}"></i>${SHORT[id]}</button>`).join('')}</div>`;}
function gainValue(r,key){return r[`vs${state.contrast}_${key}_gain`];}
function gainInterval(r,key){return [r[`vs${state.contrast}_${key}_low`],r[`vs${state.contrast}_${key}_high`]];}
function evidence(lo,hi){return lo>0?'Positive interval':hi<0?'Negative interval':lo===0&&hi===0?'No change':'Interval crosses zero';}
function features(){
 const rows=featureData(),base=state.contrast==='A'?'schedule-only A':'retuned 66',positiveAP=rows.filter(r=>gainInterval(r,'ap')[0]>0).length,positiveF1=rows.filter(r=>gainInterval(r,'f1')[0]>0).length;
 const cov=DATA.features[0];
 const table=rows.map(r=>{const ap=gainValue(r,'ap'),f1=gainValue(r,'f1'),a= gainInterval(r,'ap'),f=gainInterval(r,'f1');return `<tr><td class="model-name">${NAMES[r.model_id]}${selectedBadge(r)}<span class="feature-package">${PACKAGES[r.feature_package]||r.feature_package}</span></td><td class="num">${num(metric(r.model_id,state.contrast==='A'?'A':'reference66').n_predictors)} → ${num(r.n_predictors)}</td><td class="num direction ${ap<0?'negative':'positive'}">${pp(ap)}</td><td class="num">[${pp(a[0])}, ${pp(a[1])}]</td><td class="num direction ${f1<0?'negative':'positive'}">${pp(f1)}</td><td class="num">[${pp(f[0])}, ${pp(f[1])}]</td></tr>`;}).join('');
 return `${heading()}<div class="section-controls"><div class="segmented" role="group" aria-label="Feature comparison"><button data-contrast="A" aria-pressed="${state.contrast==='A'}">Schedule A → richer B</button><button data-contrast="66" aria-pressed="${state.contrast==='66'}">Retuned 66 → selected B</button></div><div class="hint">Paired comparison · fixed models · same flight IDs</div></div>
 <div class="kpi-grid">${kpi('Clear AP gains',positiveAP+' / 4',`Positive 95% interval versus ${base}`,'Number of classifiers whose paired average-precision interval lies entirely above zero.',true)}${kpi('Clear F1 gains',positiveF1+' / 4',`Positive 95% interval versus ${base}`,'An interval crossing zero does not establish a clear improvement in this month.')}${kpi('Paired July flights',num(cov.n_common_flights),'Identical flight IDs and labels')}${kpi('Report & origin-history match',pct(cov.added_feature_coverage,0),'Individual weather readings may be missing','Coverage means a matched weather report plus nonzero origin-history support. It does not mean all weather measurements are known.')}</div>
 <div class="grid equal">${panel('Ranking improvement · average precision',`Selected B minus ${base}. Whiskers show paired 95% intervals.`,chart('feature-ap')+'<div class="panel-foot">A positive change means better risk ranking. AP does not depend on choosing one classification threshold.</div>')}${panel('Classification improvement · F1',`Selected B minus ${base}. Differences are percentage points.`,chart('feature-f1')+'<div class="panel-foot">A and B thresholds were calibrated on the same earlier period. Intervals are conditional on the fitted models.</div>')}</div>
 <div class="insight">${state.contrast==='A'?'<strong>Richer inputs improved ranking for all four models.</strong> Their AP intervals are positive. Random Forest’s F1 interval still crosses zero; the package did not clearly improve every outcome.':'<strong>The compact additions give mixed results beyond retuning.</strong> KNN improves AP; Logistic Regression’s AP interval crosses zero; Random Forest’s AP falls. SVM kept the existing 66 features.'}</div>
 <div class="grid equal" style="margin-top:18px">${panel('What this comparison establishes','Controlled evidence, with a defined scope.',`<p class="objective-note">${state.contrast==='A'?'<strong>A → B</strong> tests the combined value of weather, historical delay patterns and scheduled airport traffic at matched settings. It does not identify the individual contribution of each source.':'<strong>Retuned 66 → B</strong> isolates the new compact additions beyond an equally retuned existing feature set. SVM’s zero change means its validation-selected package retained those 66 inputs.'}</p><p class="objective-note">Feature correlations are supporting EDA. The evidence here comes from fitted models predicting the same later flights.</p>`)}${panel('How to read the intervals','300 paired day-bootstrap draws · 31 July date blocks.',`<div class="legend"><span><i class="swatch" style="background:#236b9f"></i>Positive interval</span><span><i class="swatch" style="background:#bf8436"></i>Negative interval</span><span><i class="swatch" style="background:#8994a3"></i>Crosses zero / no change</span></div><p class="objective-note">The dot is the observed gain; the line is its interval. Crossing the zero reference means the direction is uncertain at this reporting level. These intervals describe this month and do not prove year-round performance.</p>`)}</div>
 ${panel('Feature packages & exact paired changes','All changes and limits are percentage points (pp).','<div class="table-wrap"><table><thead><tr><th>Classifier · B package</th><th class="num">Inputs</th><th class="num">Δ AP</th><th class="num">95% AP interval</th><th class="num">Δ F1</th><th class="num">95% F1 interval</th></tr></thead><tbody>'+table+'</tbody></table></div>')}`;
}
function groupRow(){return groupData().find(r=>r.group_value===state.group)||null;}
function rateDefinition(key){return {precision:'Precision = TP / (TP + FP): correct warnings among all warnings.',recall:'Recall = TP / (TP + FN): detected actual delays.',false_positive_rate:'False-positive rate = FP / (FP + TN): warnings among actual on-time flights.',false_negative_rate:'Miss rate = FN / (TP + FN): actual delays receiving no warning.'}[key];}
function reliability(){
 const r=bMetric(),groups=groupData(),selected=groupRow(),g=selected||r;
 const heat=groups.map(x=>`<tr><td><button class="model-name" style="background:transparent;padding:0;text-align:left" data-group="${esc(x.group_value)}">${esc(x.group_value)}</button><small>${num(x.n_flights)} flights</small></td>${errorKeys.map(k=>{const v=x[k],missing=v==null;const rgb=k==='false_positive_rate'?'199,124,36':k==='false_negative_rate'?'188,75,81':'35,107,159';return `<td><button class="heat-cell${missing?' missing':''}${state.group===x.group_value&&state.errorMetric===k?' active':''}" style="--cell:rgba(${rgb},${missing?0:.07+v*.22})" data-heat-group="${esc(x.group_value)}" data-heat-metric="${k}" ${tip(missing?`${x.group_value}: ${errorNames[k]} withheld; insufficient reporting support.`:`${x.group_value}: ${errorNames[k]} ${pct(v,2)}. ${rateDefinition(k)}`)} aria-label="${esc(x.group_value+' '+errorNames[k]+': '+(missing?'insufficient support':pct(v)))}">${missing?'—':pct(v)}${missing?'<small>low support</small>':''}</button></td>`;}).join('')}</tr>`).join('');
 return `${heading()}<div class="section-controls"><div class="control-row"><div class="control"><label class="control-label" for="grouping-select">Group comparison</label><select id="grouping-select" data-control="grouping">${options(Object.entries(groupingNames),state.grouping)}</select></div><div class="control"><label class="control-label" for="error-select">Rate to inspect</label><select id="error-select" data-control="errorMetric">${options(Object.entries(errorNames),state.errorMetric)}</select></div></div><span class="tag">Package B · full July cohort</span></div>
 <div class="kpi-grid">${kpi('False warnings · FP',num(r.fp),`${pct(r.fp/r.predicted_positive)} of ${num(r.predicted_positive)} warnings`,'Type I error: an on-time flight receives a delay warning.',true)}${kpi('Missed delays · FN',num(r.fn),`${pct(r.fn/r.actual_positive)} of ${num(r.actual_positive)} actual delays`,'Type II error: an actual delayed flight is not warned about.')}${kpi('False-positive rate',pct(r.fp/(r.fp+r.tn)),`${num(r.fp)} / ${num(r.fp+r.tn)} actually on-time`,rateDefinition('false_positive_rate'))}${kpi('Actual delays found',pct(r.recall),`${num(r.tp)} / ${num(r.actual_positive)} actual delays`,rateDefinition('recall'))}</div>
 <div class="grid two">${panel(`${groupingNames[state.grouping]} comparison · ${errorNames[state.errorMetric].toLowerCase()}`,'Click a group to inspect its counts and sampled flight errors.',chart('group-bars')+`<div class="panel-foot">${rateDefinition(state.errorMetric)} Unsupported rates are withheld, never plotted as zero.</div>`)}${panel(selected?esc(selected.group_value)+' · group detail':'All July flights · error counts',selected?`${num(selected.n_flights)} sampled flights · ${groupingNames[state.grouping].toLowerCase()} subgroup`:'Select a group from a bar or heatmap.',`<div class="detail-grid">${[['TP',g.tp,'Delay found'],['FP',g.fp,'False warning'],['FN',g.fn,'Missed delay'],['TN',g.tn,'Correct on-time']].map(([label,value,title])=>`<div class="detail-number"><b>${num(value)}</b><small>${label} · ${title}</small></div>`).join('')}</div><div class="details-caption">Actual delay rate: <strong>${pct(g.actual_positive/g.n_flights)}</strong><br>Precision: <strong>${pct(g.precision)}</strong> · Recall: <strong>${pct(g.recall)}</strong><br>${selected?'Group metrics use the selected subgroup’s own denominator.':'These counts describe the complete July cohort for the displayed B model.'}</div>${selected?`<div class="group-chip">Flight-list scope: ${esc(selected.group_value)}<button data-action="clear-group">Clear selection</button></div>`:''}<div class="insight warm">${state.model==='logistic_regression'?'<strong>Evening recall is 100%, but nearly every flight is warned.</strong> 2,799 of 2,804 evening flights receive a warning; the false-positive rate is 99.7%.':'<strong>Inspect both kinds of error.</strong> A low miss rate can coexist with many false warnings. The more important error depends on the cost of the action being taken.'}</div>`)}</div>
 ${panel('Reliability matrix','Each cell uses its own denominator. Select a cell to inspect that group and rate.',`<div class="table-wrap"><table class="heatmap"><thead><tr><th>${groupingNames[state.grouping]}</th><th>Precision</th><th>Recall</th><th>False-positive rate</th><th>Miss rate</th></tr></thead><tbody>${heat}</tbody></table></div><div class="panel-foot">Support rules: group n ≥200; at least 30 actual delays for recall/miss rate, 30 actual on-time flights for false-positive rate, and 30 warnings for precision. A blank is not a 0% error rate. These reporting thresholds do not establish statistical certainty.</div>`)}
 <div style="margin-top:18px">${flightPanel('errors')}</div>`;
}
function prioritization(){
 const q=getQuota(),h=getQuota('historical_risk_ranking');
 return `${heading()}<div class="section-controls"><div><label class="control-label">Review budget · fixed July cohort</label><div class="quota-buttons" role="group" aria-label="Review quota">${[.05,.1,.2].map(v=>`<button data-quota="${v}" aria-pressed="${state.quota===v}">Top ${pct(v,0)}</button>`).join('')}</div></div><div class="budget-meta">Original Python risk ranks · exact seeded tie order<br>Global quota = ceiling(${pct(state.quota,0)} × 10,000)</div></div>
 <div class="kpi-grid">${kpi('Flights to review',num(q.reviewed_flights),`Top ${pct(state.quota,0)} of the fixed 10,000-flight cohort`,'This quota changes the retrospective list, not the model’s classification threshold.',true)}${kpi('Actual delays captured',num(q.captured_delays),`${pct(q.capture_recall)} of all ${num(q.actual_positive)} delays`,'Delayed flights in the highest-ranked review list.')}${kpi('Review-list precision',pct(q.review_precision),`${num(q.captured_delays)} delays / ${num(q.reviewed_flights)} reviewed`,'Share of the review list that actually departed at least 15 minutes late.')}${kpi('Lift over random',dec(q.lift_over_prevalence,2)+'×',`Random expected precision: ${pct(q.random_expected_precision,2)}`,'Lift = review precision / overall delay prevalence. It describes concentration, not costs saved.')}</div>
 <div class="grid two">${panel('Delay capture at each review budget','Only the three predeclared quotas are evaluated; segments connect those points.',`<div class="legend"><span><i class="swatch" style="background:${COLORS[state.model]}"></i>${NAMES[state.model]}</span><span><i class="swatch" style="background:${COLORS.historical_risk_ranking}"></i>Historical risk</span><span><i class="swatch" style="background:${COLORS.random}"></i>Random expectation</span></div>`+chart('capture-curves')+'<div class="panel-foot">Capture = actual delays in the list / all 3,215 actual delays. The historical-risk ranking uses only earlier data.</div>')}${panel('What the review list contains',`${pct(state.quota,0)} capacity · ${num(q.reviewed_flights)} flights per ranking.`,chart('review-composition')+`<div class="legend"><span><i class="swatch" style="background:#236b9f"></i>Actual delays</span><span><i class="swatch" style="background:#c77c24"></i>Actually on time</span></div><div class="panel-foot">Random counts are expectations and may be fractional. Orange counts here are review-list false alerts, not the full classification-rule FP count.</div>`)}</div>
 <div class="grid equal">${panel('The capacity trade-off',`${NAMES[state.model]} · current ${pct(state.quota,0)} budget.`,`<div class="review-summary"><span>False alerts in the review list</span><b>${num(q.false_alerts)}</b></div><div class="review-summary"><span>Actual delays outside the list</span><b>${num(q.actual_positive-q.captured_delays)}</b></div><div class="review-summary"><span>Historical-risk delays captured</span><b>${num(h.captured_delays)}</b></div><div class="review-summary"><span>More delays captured than historical risk</span><b>+${num(q.captured_delays-h.captured_delays)}</b></div>`)}${panel('Useful prioritization, with limits','Ranking a completed cohort is a different exercise from issuing warnings.',`<p class="objective-note"><strong>${pct(q.review_precision)} review precision</strong> means ${num(q.captured_delays)} of the ${num(q.reviewed_flights)} highest-ranked flights actually departed late. The list still leaves ${num(q.actual_positive-q.captured_delays)} actual delays outside the review budget.</p><div class="insight">Global ranks and quotas stay fixed when you filter the table below. This analysis does not measure interventions, money saved or delays prevented.</div>`)}</div>
 ${flightPanel('review')}`;
}
function allFlightRows(){
 const p=DATA.predictions[state.model];
 return DATA.flights.map((f,i)=>({id:f[0],date:f[1],origin:f[2],destination:f[3],airline:f[4],band:f[5],actual:f[6],scheduled:f[7],cutoff:f[8],score:p.score[i],predicted:p.predicted[i],rank:p.rank[i],outcome:p.predicted[i]?(f[6]?'TP':'FP'):(f[6]?'FN':'TN')}));
}
function getFlightRows(mode){
 let rows=allFlightRows();
 if(mode==='review')rows=rows.filter(r=>r.rank<=Math.ceil(state.quota*DATA.manifest.test_rows));
 else {
  rows=rows.filter(r=>state.outcome==='all'||(state.outcome==='errors'?['FP','FN'].includes(r.outcome):r.outcome===state.outcome));
  if(state.group){const key={origin:'origin',reporting_airline:'airline',departure_time_band:'band'}[state.grouping];rows=rows.filter(r=>r[key]===state.group);}
 }
 if(state.airport!=='All')rows=rows.filter(r=>r.origin===state.airport);
 const search=state.search.trim().toLowerCase();if(search)rows=rows.filter(r=>[r.id,r.date,r.origin,r.destination,r.airline,r.band].some(v=>v.toLowerCase().includes(search)));
 const key=state.sort;rows.sort((a,b)=>state.sortDirection*(typeof a[key]==='number'?a[key]-b[key]:a[key].localeCompare(b[key]))||a.rank-b.rank);
 return rows;
}
function flightPanel(mode){
 const title=mode==='review'?'Ranked flight review list':'Sampled flights · prediction errors';
 const subtitle=mode==='review'?'Highest risk first by default. The budget always uses the original global cohort.':'Original B predictions and labels. Filter this list without changing global scorecards.';
 return panel(title,subtitle,`<div class="table-controls"><div class="control"><label class="control-label" for="airport-filter">List airport only</label><select id="airport-filter" data-list-control="airport">${options(['All','ATL','DFW','ORD'].map(v=>[v,v==='All'?'All airports':v]),state.airport)}</select></div>${mode==='errors'?`<div class="control"><label class="control-label" for="outcome-filter">Outcome</label><select id="outcome-filter" data-list-control="outcome">${options([['errors','FP + FN'],['FP','FP · false warnings'],['FN','FN · missed delays'],['all','All outcomes']],state.outcome)}</select></div>`:''}<div class="control search-control"><label class="control-label" for="flight-search">Search this list</label><input type="search" id="flight-search" data-list-control="search" placeholder="Flight ID, route, airline, date" value="${esc(state.search)}"></div><button class="secondary" data-action="reset-list">Reset list</button><div class="table-count" id="list-count"></div></div><div id="flight-table"></div><div class="list-note">Scores are uncalibrated; compare ranks within one model. The flight date is the original local schedule date. Hover a flight ID for its scheduled departure and prediction cutoff in UTC. Table filters never recompute global ranks or the scorecards above.</div>`,`<button class="secondary export-list" data-action="export-list">Export list ↓</button>`);
}
function flightTable(mode){
 const rows=getFlightRows(mode),size=25,pages=Math.max(1,Math.ceil(rows.length/size));state.listPage=Math.max(1,Math.min(pages,state.listPage));
 const start=(state.listPage-1)*size,shown=rows.slice(start,start+size);
 const heads=[['rank','Global rank'],['id','Flight ID'],['date','Local date'],['origin','Origin'],['destination','Dest.'],['airline','Airline'],['score','Risk score'],['actual','Actual delay'],['outcome','Outcome']];
 const table=`<div class="table-wrap"><table class="flight-table"><thead><tr>${heads.map(([key,label])=>`<th${['rank','score'].includes(key)?' class="num"':''} aria-sort="${state.sort===key?(state.sortDirection===1?'ascending':'descending'):'none'}"><button class="sort-button" data-sort="${key}">${label}${state.sort===key?(state.sortDirection===1?' ↑':' ↓'):''}</button></th>`).join('')}</tr></thead><tbody>${shown.map(r=>`<tr><td class="num">${num(r.rank)}</td><td ${tip(`Scheduled departure (UTC): ${r.scheduled}<br>Prediction cutoff (UTC): ${r.cutoff}<br>Departure band: ${esc(r.band)}`)}>${esc(r.id)}</td><td>${esc(r.date)}</td><td>${r.origin}</td><td>${r.destination}</td><td>${r.airline}</td><td class="num">${dec(r.score,4)}</td><td>${r.actual?'Delayed':'On time'}</td><td><span class="outcome ${r.outcome.toLowerCase()}" ${tip({TP:'True positive · delay found',FP:'False positive · false warning',FN:'False negative · missed delay',TN:'True negative · correctly on time'}[r.outcome])}>${r.outcome}</span></td></tr>`).join('')||'<tr><td colspan="9" class="empty">No flights match these list filters. Try resetting the list.</td></tr>'}</tbody></table></div><div class="pagination"><span>${rows.length?`${num(start+1)}–${num(Math.min(start+size,rows.length))} of ${num(rows.length)}`:'0 matching flights'} · 25 rows per page</span><div><button class="secondary" data-list-page="${state.listPage-1}"${state.listPage<=1?' disabled':''}>← Previous</button><span>Page ${state.listPage} / ${num(pages)}</span><button class="secondary" data-list-page="${state.listPage+1}"${state.listPage>=pages?' disabled':''}>Next →</button></div></div>`;
 return {html:table,count:`${num(rows.length)} matching flights${mode==='review'?'<br>of '+num(getQuota().reviewed_flights)+' in the global review list':''}`,rows};
}
function updateFlightTable(){const el=document.getElementById('flight-table');if(!el)return;const view=flightTable(state.page==='prioritization'?'review':'errors');el.innerHTML=view.html;document.getElementById('list-count').innerHTML=view.count;}

// Responsive SVG charts. Every quantitative axis states its measure and units.
const SVG_NS='http://www.w3.org/2000/svg';
function svgStart(w,h,title,desc=''){return `<svg xmlns="${SVG_NS}" viewBox="0 0 ${w} ${h}" width="${w}" height="${h}" role="img" aria-label="${esc(title)}"><title>${esc(title)}</title>${desc?`<desc>${esc(desc)}</desc>`:''}`;}
function line(x1,y1,x2,y2,stroke='#e5eaf0',extra=''){return `<line x1="${x1}" y1="${y1}" x2="${x2}" y2="${y2}" stroke="${stroke}" ${extra}/>`;}
function txt(x,y,text,cls='',anchor='start',extra=''){return `<text x="${x}" y="${y}" class="${cls}" text-anchor="${anchor}" ${extra}>${esc(text)}</text>`;}
function barChart(el,items,{max=1,axis='Score',formatter=pct,labelsWidth=132,rowHeight=34,click='',color=null}={}){
 const w=Math.max(280,Math.floor(el.clientWidth)),left=Math.min(labelsWidth,Math.max(98,w*.3)),right=62,top=18,bottom=43,h=top+items.length*rowHeight+bottom,span=Math.max(50,w-left-right),x=v=>left+v/max*span;
 let s=svgStart(w,h,axis,items.map(r=>r.label+': '+(r.value==null?'withheld':formatter(r.value))).join('; '));
 for(let t=0;t<=4;t++){const v=max*t/4,xx=x(v);s+=line(xx,top-6,xx,h-bottom+2);s+=txt(xx,h-bottom+20,formatter(v),'','middle');}
 items.forEach((r,i)=>{const yy=top+i*rowHeight,fill=r.color||(color||'#648eae'),missing=r.value==null,label=r.label.length>(w<380?18:24)?r.label.slice(0,w<380?16:22)+'…':r.label;
 const attr=click&&r.id?` ${click}="${esc(r.id)}" role="button" tabindex="0"`:'';
 s+=`<g${attr} ${tip(r.tip||r.label+': '+(missing?'Insufficient support':formatter(r.value)))}><title>${esc(r.label+': '+(missing?'Insufficient support':formatter(r.value)))}</title><rect class="hit" x="0" y="${yy-4}" width="${w}" height="${rowHeight}" rx="4"/>`;
 s+=txt(left-10,yy+14,label,'row-label','end');
 if(!missing)s+=`<rect x="${left}" y="${yy}" width="${Math.max(0,r.value/max*span)}" height="20" rx="3" fill="${fill}"/>`;
 s+=txt(missing?left+8:Math.min(x(r.value)+7,w-3),yy+14,missing?'— low support':formatter(r.value),'value');s+='</g>';
 });s+=txt(left+span/2,h-2,axis,'axis-title','middle')+'</svg>';el.innerHTML=s;
}
function forestChart(el,key){
 const rows=featureData(),w=Math.max(280,Math.floor(el.clientWidth)),left=w<400?109:139,right=72,top=22,rowHeight=55,h=top+rows.length*rowHeight+53,values=rows.flatMap(r=>gainInterval(r,key)).concat([0]),min=Math.min(...values),max=Math.max(...values),padding=Math.max(.002,(max-min)*.17),lo=min-padding,hi=max+padding,span=Math.max(50,w-left-right),x=v=>left+(v-lo)/(hi-lo)*span;
 let s=svgStart(w,h,`${key==='ap'?'Average precision':'F1'} gain with paired 95% intervals`);
 for(let t=0;t<=4;t++){const v=lo+(hi-lo)*t/4,xx=x(v);s+=line(xx,12,xx,h-45);s+=txt(xx,h-24,(v*100).toFixed(1),'','middle');}
 s+=line(x(0),12,x(0),h-45,'#8d9bac','stroke-dasharray="4 4"');
 rows.forEach((r,i)=>{const y=top+rowHeight*i+13,val=gainValue(r,key),[a,b]=gainInterval(r,key),c=a>0?'#236b9f':b<0?'#bf8436':'#8994a3';s+=`<g ${tip(`<strong>${NAMES[r.model_id]}</strong><br>Gain: ${pp(val,3)}<br>95% interval: [${pp(a,3)}, ${pp(b,3)}]<br>${evidence(a,b)}`)}><rect class="hit" x="0" y="${y-15}" width="${w}" height="39"/>`+txt(left-10,y+4,SHORT[r.model_id],'row-label','end')+line(x(a),y,x(b),y,c,'stroke-width="2.5"')+line(x(a),y-5,x(a),y+5,c)+line(x(b),y-5,x(b),y+5,c)+`<circle cx="${x(val)}" cy="${y}" r="4.6" fill="${c}"/>`+txt(w-1,y+4,pp(val),'value','end')+'</g>';});
 s+=txt(left+span/2,h-3,`Δ ${key==='ap'?'average precision':'F1'} (percentage points)`,'axis-title','middle')+'</svg>';el.innerHTML=s;
}
function lineChart(el,series,{title,xLabel,yLabel,xMax=1,yMax=1,reference=null,points=false}={}){
 const w=Math.max(280,Math.floor(el.clientWidth)),h=290,l=49,r=15,t=17,b=51,pw=w-l-r,ph=h-t-b,x=v=>l+v/xMax*pw,y=v=>t+(1-v/yMax)*ph;
 let s=svgStart(w,h,title,series.map(a=>a.label).join(', '));
 const yTicks=yMax===.5?5:4;
 for(let i=0;i<=yTicks;i++){const v=i/yTicks;s+=line(l,y(v*yMax),w-r,y(v*yMax));s+=txt(l-9,y(v*yMax)+4,pct(v*yMax,0),'','end');}
 for(let i=0;i<=4;i++){const v=i/4;s+=txt(x(v*xMax),h-b+21,pct(v*xMax,0),'','middle');}
 s+=line(l,t,l,h-b,'#bac7d4')+line(l,h-b,w-r,h-b,'#bac7d4');
 if(reference!=null)s+=line(l,y(reference),w-r,y(reference),'#aab6c3','stroke-dasharray="5 4"');
 series.forEach(a=>{let path='';a.points.forEach(([xx,yy],i)=>{path+=(i?'L':'M')+x(xx).toFixed(2)+','+y(yy).toFixed(2);});s+=`<path d="${path}" fill="none" stroke="${a.color}" stroke-width="${a.width||2}"${a.dash?' stroke-dasharray="'+a.dash+'"':''} opacity="${a.opacity||1}"/>`;
  if(points)for(const [xx,yy] of a.points)s+=`<g ${tip(`${a.label}<br>Review budget: ${pct(xx,0)}<br>Delay capture: ${pct(yy,2)}`)}><circle cx="${x(xx)}" cy="${y(yy)}" r="4" fill="${a.color}"/><circle class="hit" cx="${x(xx)}" cy="${y(yy)}" r="17"/></g>`;
  if(a.marker)s+=`<circle cx="${x(a.marker[0])}" cy="${y(a.marker[1])}" r="4.5" fill="${a.color}" stroke="white" stroke-width="1.5"/>`;
 });
 s+=txt(l+pw/2,h-6,xLabel,'axis-title','middle')+txt(13,t+ph/2,yLabel,'axis-title','middle',`transform="rotate(-90 13 ${t+ph/2})"`);
 s+=`<rect class="hit" data-line-hit="${el.dataset.chart}" x="${l}" y="${t}" width="${pw}" height="${ph}"/>`+'</svg>';el.innerHTML=s;
 // Keep geometry local for nearest-observation hover. Original arrays stay intact.
 el._plot={series,l,r,t,b,w,h,xMax,yMax};
}
function compositionChart(el){
 const q=getQuota(),base=getQuota('historical_risk_ranking'),n=q.reviewed_flights;
 const rows=[{name:SHORT[state.model],delays:q.captured_delays,false:q.false_alerts},{name:'Historical risk',delays:base.captured_delays,false:base.false_alerts},{name:'Random expected',delays:n*.3215,false:n*.6785}];
 const w=Math.max(280,Math.floor(el.clientWidth)),l=117,r=15,span=w-l-r,h=265;
 let s=svgStart(w,h,'Actual delays and on-time flights within the review budget');
 rows.forEach((a,i)=>{const y=32+i*69,blue=a.delays/n*span,orange=a.false/n*span;s+=txt(0,y+18,a.name,'row-label')+`<g ${tip(`${a.name}<br>${num(a.delays)} actual delays<br>${num(a.false)} actually on time<br>${pct(a.delays/n)} review precision`)}><rect x="${l}" y="${y}" width="${blue}" height="28" fill="#236b9f" rx="2"/><rect x="${l+blue}" y="${y}" width="${orange}" height="28" fill="#c77c24"/>`+txt(l,y+44,`${num(a.delays)} delays · ${num(a.false)} on time`,'value')+'</g>';});
 s+=txt(l+span/2,h-5,`${num(n)} reviewed flights per ranking`,'axis-title','middle')+'</svg>';el.innerHTML=s;
}
function drawCharts(){
 document.querySelectorAll('[data-chart]').forEach(el=>{
  const type=el.dataset.chart;
  if(type==='model-comparison'){
   let rows=MODEL_IDS.map(id=>metric(id));if(state.benchmarks)rows.push(...baselines());
   const names={f1:'Delayed-class F1',average_precision:'Average precision',accuracy:'Accuracy',precision:'Precision',recall:'Recall',roc_auc:'ROC-AUC'},key=state.comparisonMetric;
   barChart(el,rows.map(r=>({id:MODEL_IDS.includes(r.model_id)?r.model_id:null,label:SHORT[r.model_id],value:r[key],color:r.model_id===state.model?'#236b9f':r.feature_set==='baseline'?'#b6c0cb':'#8da9bf',tip:`<strong>${NAMES[r.model_id]}</strong><br>${names[key]}: ${dec(r[key],5)}<br>${r.feature_set==='baseline'?'Fixed reference':featureName(state.feature)}<br>${num(r.n_flights)} flights`})),{axis:names[key]+(key==='f1'||key==='average_precision'||key==='roc_auc'?' (0–1)':' (%)'),formatter:['f1','average_precision','roc_auc'].includes(key)?x=>dec(x,3):pct,click:'data-model'});
  }else if(type==='feature-ap')forestChart(el,'ap');
  else if(type==='feature-f1')forestChart(el,'f1');
  else if(type==='pr-curves'){
   const visible=MODEL_IDS.filter(id=>!state.hiddenCurves.includes(id));
   lineChart(el,visible.map(id=>{const r=metric(id);return {id,label:NAMES[id],color:COLORS[id],points:DATA.curves[r.candidate_id],marker:[r.recall,r.precision],width:id===state.model?2.6:1.6,opacity:id===state.model?1:.75};}),{title:'Precision–recall curves',xLabel:'Recall · actual delays detected (%)',yLabel:'Precision · correct warnings (%)',reference:.3215});
  }else if(type==='group-bars'){
   const rows=groupData();barChart(el,rows.map(r=>({id:r.group_value,label:r.group_value,value:r[state.errorMetric],color:r.group_value===state.group?'#236b9f':state.errorMetric==='false_positive_rate'?'#cc954f':state.errorMetric==='false_negative_rate'?'#c36c70':'#648eae',tip:`<strong>${esc(r.group_value)}</strong><br>${num(r.n_flights)} flights<br>${errorNames[state.errorMetric]}: ${pct(r[state.errorMetric],2)}<br>TP ${num(r.tp)} · FP ${num(r.fp)} · FN ${num(r.fn)} · TN ${num(r.tn)}`})),{axis:errorNames[state.errorMetric]+' (%)',click:'data-group',labelsWidth:155,rowHeight:39});
  }else if(type==='capture-curves'){
   const quotas=[.05,.1,.2],series=[{label:NAMES[state.model],color:COLORS[state.model],points:quotas.map(q=>[q,getQuota(state.model,q).capture_recall])},{label:'Historical risk',color:COLORS.historical_risk_ranking,dash:'5 3',points:quotas.map(q=>[q,getQuota('historical_risk_ranking',q).capture_recall])},{label:'Random expectation',color:COLORS.random,dash:'2 3',points:quotas.map(q=>[q,q])}];
   lineChart(el,series,{title:'Delay capture at predeclared review quotas',xLabel:'Flights reviewed (% of cohort)',yLabel:'Actual delays captured (%)',xMax:.2,yMax:.5,points:true});
  }else if(type==='review-composition')compositionChart(el);
 });
}
function notesHtml(){return `<h3>The main objective</h3><p>Evaluate whether familiar classifiers can identify and prioritize departures delayed by at least 15 minutes, using a historical simulation with a two-hour pre-departure cutoff.</p><h3>Four supporting objectives</h3><ul><li><strong>O1:</strong> select a classifier on earlier validation and confirm its later performance and runtime.</li><li><strong>O2:</strong> measure the paired predictive value of richer information on identical flights.</li><li><strong>O3:</strong> identify supported subgroup patterns in false warnings and missed delays.</li><li><strong>O4:</strong> quantify delay concentration in fixed 5%, 10% and 20% review lists.</li></ul><h3>Data & model selection</h3><p>The final classifiers fit a shared 40,000-flight sample covering all twelve months of 2025. The final development selection used mean delayed-class F1 with AP as tie-break. Logistic Regression with the combined feature package was selected before July outcomes were loaded. Thresholds were frozen from the earlier October calibration procedure; no July threshold repair is shown here.</p><p>July confirmation uses 10,000 natural-prevalence flights from ATL, DFW and ORD, with 3,215 actual delays (32.15%). It covers <strong>one summer month</strong>, not year-round or full-quarter performance. The source July population had 89,701 schedules and 87,298 eligible operated/known-label flights. The 10,000-row evaluation is sampled; cancelled and unknown-label flights follow the documented exclusions.</p><h3>Feature comparisons</h3><p>A = schedule and time features; reference66 = equally retuned existing 66-feature set; B = the validation-selected richer package (LR/KNN 78 inputs, SVM 66, RF 72). A/B uses matched settings and identical fitting IDs and time harmonics. A was not independently optimized. Richer B cannot isolate the separate causal value of weather, history and traffic. Paired 95% intervals use 300 day-bootstrap draws over 31 July blocks, conditional on fitted models.</p><h3>Which error matters?</h3><p><strong>FP / Type I:</strong> an on-time flight is warned about. <strong>FN / Type II:</strong> an actual delay is missed. Missing delays can matter more per case for low-cost early review, but false alerts dominate this selected rule’s workload. No operational cost data establishes a universal cost ranking for aviation.</p><ul><li>Precision = TP / (TP + FP).</li><li>Recall = TP / (TP + FN).</li><li>Miss rate = FN / (TP + FN).</li><li>False-positive rate = FP / (FP + TN).</li><li>False-warning share = FP / (TP + FP), which uses a different denominator from false-positive rate.</li><li>F1 is the harmonic mean of precision and recall. A coin does not universally score 0.50 F1. The seed-42 fair-coin result here is 0.398; always-delayed F1 is 0.487.</li><li>AP measures ranking across thresholds; prevalence (0.3215) is the uninformative reference.</li></ul><h3>Support & ranking rules</h3><p>Subgroup rates require at least 200 group flights and 30 relevant delayed, on-time or warned flights. Unsupported rates remain blank. Global risk ranks preserve the outcome-independent seed-42 hash tie order. Review K = ceiling(quota × 10,000). Filtering a flight list never recomputes global ranks, quotas or aggregate scorecards. Random counts are expectations.</p><h3>Availability assumptions & limits</h3><p>Weather delivery uses an assumed 20-minute buffer and a maximum age of 180 minutes. Historical outcomes use 28-day windows ending seven days before the cutoff. Timely outcome access and archived schedule snapshots are assumed, not verified. Aircraft rotation and current-flight actual outcomes were excluded. Scores are <strong>uncalibrated risk scores</strong>, including SVM decision values, not verified delay probabilities.</p><p>This retrospective study does not establish a deployable real-time policy, prevented delays, interventions or money saved. Reused development periods can introduce selection optimism. Only July is the new confirmation period.</p><h3>File & provenance</h3><p>This file contains the original metrics, all precision–recall curve points and all 10,000 B flight predictions for each of the four classifiers. No network connection, external library or account is required.</p><p>Run: <code>${esc(DATA.manifest.run_id)}</code><br>Cohort: <code>${esc(DATA.manifest.cohort_fingerprint)}</code></p><button class="secondary" data-action="manifest">Download source manifest ↓</button><details><summary>Inspect source checksums</summary><pre class="manifest-block">${esc(JSON.stringify(DATA.manifest.files,null,2))}</pre></details>`;}
function announce(text){const el=document.getElementById('announcer');if(el)el.textContent=text;}
function render({announceChange=true}={}){
 const el=document.getElementById('report');if(!el)return;
 document.querySelectorAll('[data-page]').forEach(b=>b.setAttribute('aria-selected',String(b.dataset.page===state.page)));
 el.setAttribute('aria-labelledby','tab-'+state.page);
 el.innerHTML=({performance,features,reliability,prioritization}[state.page])();
 updateFlightTable();drawCharts();
 if(announceChange)announce(`${PAGES[state.page].title}. ${NAMES[state.model]}, ${state.page==='performance'?featureName(state.feature):'package B'}.`);
 hideTooltip();
}
function exportRows(){
 if(state.page==='performance'){const rows=MODEL_IDS.map(id=>metric(id));return state.benchmarks?rows.concat(baselines()):rows;}
 if(state.page==='features')return featureData().flatMap(r=>['ap','f1'].map(k=>({model:NAMES[r.model_id],contrast:state.contrast==='A'?'B minus schedule A':'B minus retuned 66',metric:k,gain:gainValue(r,k),ci95_low:gainInterval(r,k)[0],ci95_high:gainInterval(r,k)[1],n_flights:r.n_flights,run_id:r.run_id})));
 if(state.page==='reliability')return groupData();
 return [getQuota(),getQuota('historical_risk_ranking'),{model_id:'random_expectation',feature_set:'expectation',capacity_fraction:state.quota,n_flights:10000,actual_positive:3215,reviewed_flights:getQuota().reviewed_flights,captured_delays:getQuota().reviewed_flights*.3215,false_alerts:getQuota().reviewed_flights*.6785,review_precision:.3215,capture_recall:state.quota,lift_over_prevalence:1}];
}
function csvText(rows){if(!rows.length)return '';const keys=[...new Set(rows.flatMap(r=>Object.keys(r)))],quote=x=>{let s=x==null?'':String(x);if(/^[=+@\-]/.test(s)&&typeof x!=='number')s="'"+s;return /[",\r\n]/.test(s)?'"'+s.replace(/"/g,'""')+'"':s;};return '\ufeff'+keys.map(quote).join(',')+'\r\n'+rows.map(r=>keys.map(k=>quote(r[k])).join(',')).join('\r\n');}
function download(content,name,type){const url=URL.createObjectURL(new Blob([content],{type})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);announce('Downloaded '+name);}
function exportCsv(rows,name){download(csvText(rows),name,'text/csv;charset=utf-8');}
function hideTooltip(){const el=document.getElementById('tooltip');if(el)el.classList.remove('is-visible');}
function showTooltip(html,x,y){const el=document.getElementById('tooltip');if(!el)return;el.innerHTML=html;el.classList.add('is-visible');const rect=el.getBoundingClientRect();el.style.left=Math.max(8,Math.min(x+14,window.innerWidth-rect.width-10))+'px';el.style.top=Math.max(8,Math.min(y+14,window.innerHeight-rect.height-10))+'px';}
function nearestPoint(points,x){let lo=0,hi=points.length-1;const asc=points[0][0]<=points[hi][0];while(lo<hi){const mid=(lo+hi)>>1;if(asc?points[mid][0]<x:points[mid][0]>x)lo=mid+1;else hi=mid;}return [points[lo],points[Math.max(0,lo-1)]].reduce((a,b)=>Math.abs(a[0]-x)<Math.abs(b[0]-x)?a:b);}
function lineHover(target,e){const chartEl=target.closest('[data-chart]'),p=chartEl?chartEl._plot:null;if(!p)return;const box=target.ownerSVGElement.getBoundingClientRect(),xx=(e.clientX-box.left)/box.width*p.w,share=Math.max(0,Math.min(1,(xx-p.l)/(p.w-p.l-p.r))),value=share*p.xMax;let html=`<strong>${chartEl.dataset.chart==='pr-curves'?'Recall':'Review budget'} ≈ ${pct(value,1)}</strong><br><span>Nearest retained observations</span>`;for(const a of p.series){const v=nearestPoint(a.points,value);html+=`<br>${esc(a.label)}: ${pct(v[1],2)} ${chartEl.dataset.chart==='pr-curves'?'precision':'capture'} (at ${pct(v[0],2)})`;}showTooltip(html,e.clientX,e.clientY);}
function navigate(page){if(!PAGES[page])return;state.page=page;state.listPage=1;state.search='';state.airport='All';history.replaceState(null,'','#'+page);render();window.scrollTo({top:0,behavior:'instant'});}
function resetList(){Object.assign(state,{airport:'All',search:'',outcome:'errors',listPage:1,sort:'rank',sortDirection:1,group:null});render();}
function init(){
 const hash=location.hash.slice(1);if(PAGES[hash])state.page=hash;
 document.getElementById('notes-body').innerHTML=notesHtml();
 render({announceChange:false});
 document.addEventListener('change',e=>{const el=e.target;if(el.dataset.control){const key=el.dataset.control;state[key]=key==='benchmarks'?el.checked:el.value;if(key==='model'){state.group=null;state.listPage=1;}if(key==='grouping')state.group=null;render();}else if(el.dataset.listControl){state[el.dataset.listControl]=el.value;state.listPage=1;updateFlightTable();announce('Flight list filters updated. Global metrics unchanged.');}});
 document.addEventListener('input',e=>{if(e.target.dataset.listControl==='search'){state.search=e.target.value;state.listPage=1;updateFlightTable();}});
 document.addEventListener('click',e=>{
  const t=e.target.closest('[data-page],[data-model],[data-contrast],[data-quota],[data-group],[data-heat-group],[data-curve],[data-action],[data-sort],[data-list-page]');if(!t)return;
  if(t.dataset.page)navigate(t.dataset.page);
  else if(t.dataset.model){state.model=t.dataset.model;state.group=null;state.listPage=1;render();}
  else if(t.dataset.contrast){state.contrast=t.dataset.contrast;render();}
  else if(t.dataset.quota){state.quota=Number(t.dataset.quota);state.listPage=1;render();}
  else if(t.dataset.group){state.group=state.group===t.dataset.group?null:t.dataset.group;state.listPage=1;render();}
  else if(t.dataset.heatGroup){state.group=t.dataset.heatGroup;state.errorMetric=t.dataset.heatMetric;state.listPage=1;render();}
  else if(t.dataset.curve){const id=t.dataset.curve;state.hiddenCurves=state.hiddenCurves.includes(id)?state.hiddenCurves.filter(x=>x!==id):[...state.hiddenCurves,id];render();}
  else if(t.dataset.sort){state.sortDirection=state.sort===t.dataset.sort?-state.sortDirection:1;state.sort=t.dataset.sort;state.listPage=1;updateFlightTable();}
  else if(t.dataset.listPage){state.listPage=Number(t.dataset.listPage);updateFlightTable();}
  else if(t.dataset.action){const action=t.dataset.action;if(action==='notes')document.getElementById('study-notes').showModal();else if(action==='close-notes')document.getElementById('study-notes').close();else if(action==='print')window.print();else if(action==='clear-group'){state.group=null;state.listPage=1;render();}else if(action==='reset-list')resetList();else if(action==='export')exportCsv(exportRows(),'july-'+state.page+'-data.csv');else if(action==='export-list')exportCsv(getFlightRows(state.page==='prioritization'?'review':'errors'),'july-'+state.model+'-'+(state.page==='prioritization'?'top-'+Math.round(state.quota*100)+'pct':'errors')+'-filtered.csv');else if(action==='manifest')download(JSON.stringify(DATA.manifest,null,2)+'\n','july-source-manifest.json','application/json');}
 });
 document.addEventListener('keydown',e=>{
  if((e.key==='Enter'||e.key===' ')&&e.target.matches('g[data-model],g[data-group]')){e.preventDefault();e.target.dispatchEvent(new MouseEvent('click',{bubbles:true}));}
  if(e.target.matches('[data-page]')&&['ArrowRight','ArrowDown','ArrowLeft','ArrowUp','Home','End'].includes(e.key)){e.preventDefault();const ids=Object.keys(PAGES),i=ids.indexOf(state.page),next=e.key==='Home'?0:e.key==='End'?3:(i+(['ArrowRight','ArrowDown'].includes(e.key)?1:3))%4;navigate(ids[next]);document.getElementById('tab-'+ids[next]).focus();}
 });
 document.addEventListener('pointermove',e=>{const line=e.target.closest('[data-line-hit]');if(line){lineHover(line,e);return;}const target=e.target.closest('[data-tip]');if(target)showTooltip(target.dataset.tip,e.clientX,e.clientY);else hideTooltip();});
 document.addEventListener('focusin',e=>{const t=e.target.closest('[data-tip]');if(t){const r=t.getBoundingClientRect();showTooltip(t.dataset.tip,r.left,r.bottom);}else hideTooltip();});
 document.addEventListener('pointerleave',hideTooltip);window.addEventListener('scroll',hideTooltip,{passive:true});
 let width=window.innerWidth;window.addEventListener('resize',()=>{if(window.innerWidth!==width){width=window.innerWidth;drawCharts();hideTooltip();}});
 window.addEventListener('hashchange',()=>{const page=location.hash.slice(1);if(PAGES[page]){state.page=page;render();}});
}
window.DashboardCore = {DATA,state,DEFAULTS,MODEL_IDS,metric,getQuota,groupData,featureData,gainValue,gainInterval,allFlightRows,getFlightRows,flightTable,performance,features,reliability,prioritization,exportRows,csvText,nearestPoint,drawCharts,barChart,forestChart,lineChart,compositionChart};
if(!window.__DASHBOARD_TEST_MODE)init();
})();
